async function readJsonFile(path: string) {
  const file = await readFile(path, 'utf8')
  return JSON.parse(file)
}

/**
 * EINE FEHLERANTWORT, DIE NICHTS UEBER DIE PLATTE VERRAET.
 *
 * ══ WAS SIE VERHINDERT ═════════════════════════════════════════════════════
 *
 * `String(e)` auf einem Systemfehler von Node IST der Pfad:
 *
 *   {"ok":false,"error":"Error: ENOENT: no such file or directory,
 *                        open '/etc/mupibox/profile/kalea/darstellung.json'"}
 *
 * Damit geht die Ablagestruktur der Box an jeden, der eine Anfrage schicken
 * kann — und auf einer Bestandsbox ist `interfacelogin.state` in der Vorlage
 * `false`, die Verwaltung steht also offen im Netz. Denselben Fund hat
 * fehlergrund.ts am 07.08.2026 fuer die Protokoll-Wege festgehalten; die
 * uebrigen Wege blieben stehen.
 *
 * ══ DIE SCHWESTERROUTE WAR KEIN VORBILD ════════════════════════════════════
 *
 * AUDIT-2026-09-19 Rang 10 (f) nennt `String((e as Error)?.message ?? e)` als
 * die bessere der beiden Schreibweisen — sie „schickt nur die Meldung". Das
 * ist nachgemessen FALSCH: die Meldung eines Systemfehlers IST die Zeile mit
 * dem Pfad darin, `String(e)` stellt ihr nur noch `Error: ` voran. Beide
 * Schreibweisen lecken gleich viel; angleichen haette nichts behoben.
 *
 * ══ DIE FORM BLEIBT, DER INHALT NICHT ══════════════════════════════════════
 *
 * Der Rumpf wird vom Aufrufer gebaut (`rumpf(grund)`), damit jeder Weg seine
 * Feldnamen behaelt — `error`, `hinweis`, `detail` heissen in der Oberflaeche
 * verschieden, und ein Umbenennen hier waere eine stille Aenderung an einer
 * Schnittstelle, die dieser Umbau gar nicht meint.
 *
 * VOLLSTAENDIG INS JOURNAL. Was nach draussen geht, ist knapp; wer die Box
 * betreut, soll den ganzen Fehler sehen — sonst waere er nur verschwunden
 * statt versteckt.
 */
function fehlerAntwort(
  res: express.Response,
  status: number,
  wo: string,
  fehler: unknown,
  rumpf: (grund: string) => Record<string, unknown>,
): void {
  console.warn(`${new Date().toLocaleString()}: [MixPi-Server] ${wo}:`, fehler)
  res.status(status).json(rumpf(grundNachAussen(fehler)))
}

// Opt-in TLS: {cert,key} from MUPIBOX_TLS_DIR (default /etc/mupibox/tls) when both
// files exist, else null → plain HTTP. Shared with the backend-player.
function readTlsCert(): { cert: Buffer; key: Buffer } | null {
  const dir = process.env.MUPIBOX_TLS_DIR || '/etc/mupibox/tls'
  const certPath = path.join(dir, 'cert.pem')
  const keyPath = path.join(dir, 'key.pem')
  try {
    if (fs.existsSync(certPath) && fs.existsSync(keyPath)) {
      return { cert: fs.readFileSync(certPath), key: fs.readFileSync(keyPath) }
    }
  } catch {
    /* fall through to HTTP */
  }
  return null
}

// Auto-generate a self-signed TLS cert into MUPIBOX_TLS_DIR if none exists, so the
// box serves HTTPS out of the box.
//
// HIER STAND ALS BEGRUENDUNG: "needed to set up Spotify from ANOTHER computer
// (the redirect URI must be https; the loopback-IP exception only works on the
// box)". DAS GILT SEIT BACKLOG E22/R1 NICHT MEHR: die Einrichtungsseite schickt
// eine FESTE redirect_uri (http://127.0.0.1:8200/spotify) und ist selbst gar
// kein Rueckweg mehr — die Einrichtung vom Laptop laeuft ueber schlichtes
// http://<box>:8200/spotify, ohne Zeugnis und ohne Warnung. Genau die Warnung
// war eine der drei Beschwerden, die E22 abgeschafft hat.
//
// DER HTTPS-MODUS BLEIBT TROTZDEM (er ist fuer sich nuetzlich und niemand soll
// nach einem Update vor einer toten Adresse stehen) — er ist fuer Spotify nur
// nicht mehr NOETIG. Wer ihn abbauen will, muss zuerst nachsehen, wer sonst noch
// auf 8443 zeigt; ein Lesezeichen auf https://<box>:8443/spotify funktioniert
// weiterhin.
//
// The cert covers localhost, 127.0.0.1, the hostname and every non-internal IPv4,
// so a browser on the LAN can reach it. Only in production (the box, where this
// server also serves the frontend) and skippable via MUPIBOX_NO_AUTO_TLS=1; a
// failure (e.g. no openssl) is non-fatal — it just falls back to HTTP.
function ensureTlsCert(): void {
  if (!productionServe || process.env.MUPIBOX_NO_AUTO_TLS === '1') return
  const dir = process.env.MUPIBOX_TLS_DIR || '/etc/mupibox/tls'
  const certPath = path.join(dir, 'cert.pem')
  const keyPath = path.join(dir, 'key.pem')
  try {
    if (fs.existsSync(certPath) && fs.existsSync(keyPath)) return
    fs.mkdirSync(dir, { recursive: true })
    const host = os.hostname() || 'mupibox'
    const ips = Object.values(os.networkInterfaces())
      .flat()
      .filter(
        (i): i is os.NetworkInterfaceInfo => !!i && (i.family === 'IPv4' || (i.family as unknown) === 4) && !i.internal,
      )
      .map((i) => i.address)
    const san = ['DNS:localhost', `DNS:${host}`, 'IP:127.0.0.1', ...ips.map((ip) => `IP:${ip}`)].join(',')
    execFileSync(
      'openssl',
      [
        'req',
        '-x509',
        '-newkey',
        'rsa:2048',
        '-nodes',
        '-keyout',
        keyPath,
        '-out',
        certPath,
        '-days',
        '3650',
        '-subj',
        `/CN=${host}`,
        '-addext',
        `subjectAltName=${san}`,
      ],
      { stdio: 'ignore' },
    )
    try {
      fs.chmodSync(keyPath, 0o600)
    } catch {
      /* best effort */
    }
    console.log(
      `${new Date().toLocaleString()}: [mupibox-backend-api] Auto-generated self-signed TLS cert (SAN: ${san})`,
    )
  } catch (err) {
    console.warn(
      `${new Date().toLocaleString()}: [mupibox-backend-api] TLS auto-generation failed, serving HTTP:`,
      err instanceof Error ? err.message : err,
    )
  }
}

